// The real FIFA World Cup 26 knockout bracket: the fixed R32→Final slot tree (Regulations
// §12.6–12.11) plus the Annex C third-placed allocation. Replaces the placeholder seeding
// for the genuine 12-group / 32-qualifier format.
import type { Rng } from "../domain/rng";
import type { TeamId, TableRow, MatchResult } from "../domain/types";
import type { StrengthModel } from "../model/strength-model";
import type { GroupResult } from "./group-engine";
import { resolveMatch } from "./knockout";

/** Order-independent key for a knockout tie between two teams. */
export function pairKey(a: TeamId, b: TeamId): string {
  return a < b ? `${a}|${b}` : `${b}|${a}`;
}

/**
 * Index played knockout ties by team pair → winner, so the simulation can condition on results
 * already on the board. A level score resolves via the penalty shootout when one is recorded;
 * without one there is no derivable winner, so the tie falls back to being simulated.
 */
export function decidedWinners(played: readonly MatchResult[]): Map<string, TeamId> {
  const decided = new Map<string, TeamId>();
  for (const m of played) {
    if (m.homeGoals > m.awayGoals) decided.set(pairKey(m.home, m.away), m.home);
    else if (m.homeGoals < m.awayGoals) decided.set(pairKey(m.home, m.away), m.away);
    else if (m.shootoutHome !== undefined && m.shootoutAway !== undefined && m.shootoutHome !== m.shootoutAway) {
      decided.set(pairKey(m.home, m.away), m.shootoutHome > m.shootoutAway ? m.home : m.away);
    }
  }
  return decided;
}

type Slot = { winner: string } | { runner: string } | { third: string };

// Round of 32 (M73–M88), Regulations §12.6. `third: X` = the best-third assigned to face the
// winner of group X (resolved via Annex C).
const R32: { match: number; a: Slot; b: Slot }[] = [
  { match: 73, a: { runner: "A" }, b: { runner: "B" } },
  { match: 74, a: { winner: "E" }, b: { third: "E" } },
  { match: 75, a: { winner: "F" }, b: { runner: "C" } },
  { match: 76, a: { winner: "C" }, b: { runner: "F" } },
  { match: 77, a: { winner: "I" }, b: { third: "I" } },
  { match: 78, a: { runner: "E" }, b: { runner: "I" } },
  { match: 79, a: { winner: "A" }, b: { third: "A" } },
  { match: 80, a: { winner: "L" }, b: { third: "L" } },
  { match: 81, a: { winner: "D" }, b: { third: "D" } },
  { match: 82, a: { winner: "G" }, b: { third: "G" } },
  { match: 83, a: { runner: "K" }, b: { runner: "L" } },
  { match: 84, a: { winner: "H" }, b: { runner: "J" } },
  { match: 85, a: { winner: "B" }, b: { third: "B" } },
  { match: 86, a: { winner: "J" }, b: { runner: "H" } },
  { match: 87, a: { winner: "K" }, b: { third: "K" } },
  { match: 88, a: { runner: "D" }, b: { runner: "G" } },
];

// Later rounds reference earlier match winners (§12.7–12.11). M103 (third-place play-off) is
// omitted — it affects neither the champion nor the finalists.
const TREE: { match: number; a: number; b: number }[] = [
  { match: 89, a: 74, b: 77 }, { match: 90, a: 73, b: 75 }, { match: 91, a: 76, b: 78 }, { match: 92, a: 79, b: 80 },
  { match: 93, a: 83, b: 84 }, { match: 94, a: 81, b: 82 }, { match: 95, a: 86, b: 88 }, { match: 96, a: 85, b: 87 },
  { match: 97, a: 89, b: 90 }, { match: 98, a: 93, b: 94 }, { match: 99, a: 91, b: 92 }, { match: 100, a: 95, b: 96 },
  { match: 101, a: 97, b: 98 }, { match: 102, a: 99, b: 100 },
  { match: 104, a: 101, b: 102 },
];

const SEMI_MATCHES = [97, 98, 99, 100];
const FINAL_MATCHES = [101, 102];

export interface R32Matchup {
  match: number;
  home: TeamId;
  away: TeamId;
}

export interface WorldCupBracket {
  matchups: R32Matchup[];
}

type AnnexTable = Readonly<Record<string, Readonly<Record<string, string>>>>;

/** Rank the 12 third-placed teams (no head-to-head): points → GD → goals → team id. */
function bestThirdGroups(thirds: { group: string; row: TableRow }[]): string[] {
  return [...thirds]
    .sort((a, b) => {
      if (a.row.points !== b.row.points) return b.row.points - a.row.points;
      if (a.row.goalDifference !== b.row.goalDifference) return b.row.goalDifference - a.row.goalDifference;
      if (a.row.goalsFor !== b.row.goalsFor) return b.row.goalsFor - a.row.goalsFor;
      return a.group.localeCompare(b.group);
    })
    .slice(0, 8)
    .map((t) => t.group);
}

/** Resolve the fixed slot tree + Annex C into 16 concrete round-of-32 matchups. */
export function buildWorldCupBracket(results: GroupResult[], annex: AnnexTable): WorldCupBracket {
  const byGroup = new Map(results.map((r) => [r.group, r.table]));
  const rowAt = (g: string, pos: number): TeamId => {
    const t = byGroup.get(g);
    if (!t) throw new Error(`buildWorldCupBracket: missing group ${g} (need the 12 groups A–L)`);
    const row = t.find((x) => x.position === pos);
    if (!row) throw new Error(`group ${g} has no team in position ${pos}`);
    return row.team;
  };

  const thirds = results.map((r) => ({ group: r.group, row: r.table.find((x) => x.position === 3)! }));
  const qualifyingThirds = bestThirdGroups(thirds);
  const key = [...qualifyingThirds].sort().join("");
  const assignment = annex[key];
  if (!assignment) throw new Error(`no Annex C entry for third-placed combination {${key}}`);

  const resolveSlot = (slot: Slot): TeamId => {
    if ("winner" in slot) return rowAt(slot.winner, 1);
    if ("runner" in slot) return rowAt(slot.runner, 2);
    return rowAt(assignment[slot.third], 3); // third-placed team assigned to this winner
  };

  return {
    matchups: R32.map((m) => ({ match: m.match, home: resolveSlot(m.a), away: resolveSlot(m.b) })),
  };
}

export interface WorldCupKnockoutResult {
  champion: TeamId;
  finalists: TeamId[];
  semifinalists: TeamId[];
}

/**
 * Play the full bracket from the R32 matchups through the fixed tree to the final.
 * `decided` (from {@link decidedWinners}) pins any tie that has already been played, so the run
 * conditions on real results and only simulates what is still to come.
 */
export function playWorldCupKnockout(
  bracket: WorldCupBracket,
  model: StrengthModel,
  rng: Rng,
  decided?: ReadonlyMap<string, TeamId>,
): WorldCupKnockoutResult {
  const resolve = (home: TeamId, away: TeamId): TeamId => {
    const known = decided?.get(pairKey(home, away));
    return known === home || known === away ? known : resolveMatch(model, home, away, rng);
  };
  const winnerOf = new Map<number, TeamId>();
  for (const m of bracket.matchups) {
    winnerOf.set(m.match, resolve(m.home, m.away));
  }
  for (const g of TREE) {
    winnerOf.set(g.match, resolve(winnerOf.get(g.a)!, winnerOf.get(g.b)!));
  }
  return {
    champion: winnerOf.get(104)!,
    finalists: FINAL_MATCHES.map((m) => winnerOf.get(m)!),
    semifinalists: SEMI_MATCHES.map((m) => winnerOf.get(m)!),
  };
}

src/engine/elimination.ts.source:
// Mathematical elimination: which teams can no longer reach the round of 32.
//
// A team is "out" only when it CANNOT finish in the top three of its group under any completion
// of the remaining matches — because 1st/2nd qualify outright and 3rd is at least a best-third
// candidate, so finishing last (4th) is the only certain elimination. The test is intentionally
// *sound* (it never flags a team that still has a path): it reasons on POINTS only, treating any
// points tie as resolvable in the trailing team's favour (the right scoreline can always win the
// goal-difference/head-to-head tiebreaks). It is therefore conservative — a team that can finish
// 3rd but realistically never as a *best* third still shows ~0% in the Monte Carlo, not here.
import type { TeamId } from "../domain/types";
import type { GroupInput } from "./group-engine";
import type { TournamentInput } from "./simulate";

const WIN = 3;
const DRAW = 1;
const QUALIFYING_PLACES = 3; // top three of a group can still reach the last 32

/** Points each team has already banked from the played matches. */
function basePoints(group: GroupInput): Map<TeamId, number> {
  const pts = new Map<TeamId, number>(group.teams.map((t) => [t.id, 0]));
  for (const m of group.played) {
    if (m.homeGoals > m.awayGoals) pts.set(m.home, (pts.get(m.home) ?? 0) + WIN);
    else if (m.homeGoals < m.awayGoals) pts.set(m.away, (pts.get(m.away) ?? 0) + WIN);
    else {
      pts.set(m.home, (pts.get(m.home) ?? 0) + DRAW);
      pts.set(m.away, (pts.get(m.away) ?? 0) + DRAW);
    }
  }
  return pts;
}

/**
 * Teams in a group that are mathematically eliminated from a top-three finish. Enumerates every
 * win/draw/loss combination of the remaining fixtures (3^k, k tiny for a 4-team group) and keeps
 * a team only if *no* combination leaves it with at most two rivals strictly above it on points.
 */
export function eliminatedFromGroup(group: GroupInput): TeamId[] {
  const teams = group.teams.map((t) => t.id);
  const base = basePoints(group);
  const remaining = group.remaining;
  const combos = 3 ** remaining.length;

  const out: TeamId[] = [];
  for (const team of teams) {
    let canReachTopThree = false;
    for (let c = 0; c < combos && !canReachTopThree; c++) {
      const pts = new Map(base);
      let code = c;
      for (const fx of remaining) {
        const outcome = code % 3; // 0 = home win, 1 = draw, 2 = away win
        code = Math.floor(code / 3);
        if (outcome === 0) pts.set(fx.home, pts.get(fx.home)! + WIN);
        else if (outcome === 2) pts.set(fx.away, pts.get(fx.away)! + WIN);
        else {
          pts.set(fx.home, pts.get(fx.home)! + DRAW);
          pts.set(fx.away, pts.get(fx.away)! + DRAW);
        }
      }
      const mine = pts.get(team)!;
      let strictlyAbove = 0;
      for (const other of teams) {
        if (other !== team && pts.get(other)! > mine) strictlyAbove++;
      }
      if (strictlyAbove < QUALIFYING_PLACES) canReachTopThree = true;
    }
    if (!canReachTopThree) out.push(team);
  }
  return out;
}

/** All mathematically eliminated teams across the tournament's groups. */
export function eliminatedTeams(input: TournamentInput): Set<TeamId> {
  const out = new Set<TeamId>();
  for (const group of input.groups) {
    for (const team of eliminatedFromGroup(group)) out.add(team);
  }
  return out;
}

src/engine/group-engine.ts.source:
// GroupEngine — completes a group's remaining fixtures by sampling the strength model, ranks
// the final table (FIFA tiebreakers), and selects qualifiers for the 2026 knockout stage.
import type { Rng } from "../domain/rng";
import type { MatchResult, TableRow, TeamId, TeamMeta } from "../domain/types";
import type { StrengthModel } from "../model/strength-model";
import { rankGroup } from "./standings";

export interface RemainingFixture {
  home: TeamId;
  away: TeamId;
}

export interface GroupInput {
  group: string;
  teams: TeamMeta[];
  played: MatchResult[];
  remaining: RemainingFixture[];
}

export interface GroupResult {
  group: string;
  table: TableRow[];
}

/** Sample every remaining fixture, then rank the completed group. */
export function completeGroup(input: GroupInput, model: StrengthModel, rng: Rng): GroupResult {
  const sampled: MatchResult[] = input.remaining.map((fx) => {
    const score = model.sampleScore(fx.home, fx.away, rng);
    return { home: fx.home, away: fx.away, homeGoals: score.home, awayGoals: score.away };
  });
  return {
    group: input.group,
    table: rankGroup(input.teams, [...input.played, ...sampled]),
  };
}

export interface Qualifiers {
  winners: TeamId[];
  runnersUp: TeamId[];
  bestThirds: TeamId[];
}

export interface SelectOptions {
  /** How many third-placed teams advance (8 in the 2026 format). */
  bestThirds?: number;
  /** Optional conduct/ranking metadata for breaking ties among third-placed teams. */
  meta?: ReadonlyMap<TeamId, TeamMeta>;
}

const rowAt = (r: GroupResult, position: number): TableRow => {
  const row = r.table.find((x) => x.position === position);
  if (!row) throw new Error(`group ${r.group} has no team in position ${position}`);
  return row;
};

/**
 * Pick winners (1st), runners-up (2nd), and the N best third-placed teams across groups.
 * Third-placed ranking (no head-to-head — different groups):
 *   points → goal difference → goals scored → conduct → FIFA ranking.
 */
export function selectQualifiers(results: GroupResult[], opts: SelectOptions = {}): Qualifiers {
  const bestThirds = opts.bestThirds ?? 8;
  const meta = opts.meta;

  const thirds = results.map((r) => rowAt(r, 3));
  const ranked = [...thirds].sort((a, b) => {
    if (a.points !== b.points) return b.points - a.points;
    if (a.goalDifference !== b.goalDifference) return b.goalDifference - a.goalDifference;
    if (a.goalsFor !== b.goalsFor) return b.goalsFor - a.goalsFor;
    const ac = meta?.get(a.team)?.conduct ?? 0;
    const bc = meta?.get(b.team)?.conduct ?? 0;
    if (ac !== bc) return bc - ac;
    const ar = meta?.get(a.team)?.fifaRank ?? Number.POSITIVE_INFINITY;
    const br = meta?.get(b.team)?.fifaRank ?? Number.POSITIVE_INFINITY;
    return ar - br;
  });

  return {
    winners: results.map((r) => rowAt(r, 1).team),
    runnersUp: results.map((r) => rowAt(r, 2).team),
    bestThirds: ranked.slice(0, bestThirds).map((r) => r.team),
  };
}

