// KnockoutEngine — single-elimination bracket with the S1 two-stage draw resolver.
//
// SEEDING CAVEAT: the official 2026 bracket slot tree (and the 495-scenario third-place
// allocation) come from the FIFA Regulations PDF — not yet transcribed. `seedBracket` uses a
// documented PLACEHOLDER seeding that only guarantees a structurally valid bracket with no
// first-round same-group clashes. Champion probabilities are directionally correct but not
// the official bracket until the real tables land (see docs/13-spike-findings.md, S6).
import type { Rng } from "../domain/rng";
import type { TeamId } from "../domain/types";
import type { StrengthModel } from "../model/strength-model";

const SHOOTOUT_TILT = 0.2; // penalties compress skill toward a coin flip (spike S1)

/** Play one knockout tie: regulation via the model; a drawn game goes to a tilted shootout. */
export function resolveMatch(model: StrengthModel, home: TeamId, away: TeamId, rng: Rng): TeamId {
  const score = model.sampleScore(home, away, rng);
  if (score.home > score.away) return home;
  if (score.away > score.home) return away;
  const pHome = model.winProbability?.(home, away) ?? 0.5;
  const shootout = 0.5 + SHOOTOUT_TILT * (pHome - 0.5);
  return rng() < shootout ? home : away;
}

export interface Qualifiers {
  winners: TeamId[];
  runnersUp: TeamId[];
  bestThirds: TeamId[];
}

function isPowerOfTwo(n: number): boolean {
  return n > 0 && (n & (n - 1)) === 0;
}

/**
 * Order qualifiers into a single-elim seed list (match i = seeds[2i] vs seeds[2i+1]).
 * Placeholder seeding: winners interleaved with runners-up + best-thirds, then a repair pass
 * removes any first-round same-group pairing.
 */
export function seedBracket(q: Qualifiers, groupOf: ReadonlyMap<TeamId, string>): TeamId[] {
  const total = q.winners.length + q.runnersUp.length + q.bestThirds.length;
  if (!isPowerOfTwo(total)) {
    throw new Error(`knockout field must be a power of two, got ${total}`);
  }
  // Interleave winners with the rest so strong sides (group winners) start apart.
  const rest = [...q.runnersUp, ...q.bestThirds];
  const seeds: TeamId[] = [];
  const maxLen = Math.max(q.winners.length, rest.length);
  for (let i = 0; i < maxLen; i++) {
    if (i < q.winners.length) seeds.push(q.winners[i]);
    if (i < rest.length) seeds.push(rest[i]);
  }
  repairSameGroup(seeds, groupOf);
  return seeds;
}

/** Swap teams so no first-round pair (2i, 2i+1) shares a group, when avoidable. */
function repairSameGroup(seeds: TeamId[], groupOf: ReadonlyMap<TeamId, string>): void {
  for (let i = 0; i < seeds.length; i += 2) {
    if (groupOf.get(seeds[i]) !== groupOf.get(seeds[i + 1])) continue;
    for (let j = 0; j < seeds.length; j++) {
      if (j === i || j === i + 1) continue;
      const partner = j % 2 === 0 ? j + 1 : j - 1;
      const okHere = groupOf.get(seeds[i]) !== groupOf.get(seeds[j]);
      const okThere = groupOf.get(seeds[partner]) !== groupOf.get(seeds[i + 1]);
      if (okHere && okThere) {
        [seeds[i + 1], seeds[j]] = [seeds[j], seeds[i + 1]];
        break;
      }
    }
  }
}

export interface KnockoutResult {
  champion: TeamId;
  rounds: number;
  /** Round number each team reached (0 = lost round 1; `rounds` = champion). */
  reached: Map<TeamId, number>;
}

/** Play the full single-elimination bracket from a seed list. */
export function playKnockout(seeds: TeamId[], model: StrengthModel, rng: Rng): KnockoutResult {
  if (!isPowerOfTwo(seeds.length)) {
    throw new Error(`bracket must be a power of two, got ${seeds.length}`);
  }
  const reached = new Map<TeamId, number>(seeds.map((t) => [t, 0]));
  let alive = seeds;
  let round = 0;
  while (alive.length > 1) {
    round += 1;
    const next: TeamId[] = [];
    for (let i = 0; i < alive.length; i += 2) {
      const winner = resolveMatch(model, alive[i], alive[i + 1], rng);
      reached.set(winner, round);
      next.push(winner);
    }
    alive = next;
  }
  return { champion: alive[0], rounds: round, reached };
}

src/engine/simulate.ts.source:
// Monte Carlo runner + Aggregator for the group stage.
// Plays the remaining group matches N times under a strength model and counts how often each
// team wins its group, finishes runner-up, takes a best-third slot, and escapes the group.
// Pure given (input, model, seed, sims) → reproducible ResultSet (NFR2).
import { mulberry32 } from "../domain/rng";
import type { MatchResult, TeamId } from "../domain/types";
import { completeGroup, selectQualifiers, type GroupInput } from "./group-engine";
import type { StrengthModel } from "../model/strength-model";

export interface TournamentInput {
  groups: GroupInput[];
  /** How many third-placed teams advance (8 in the 2026 format). */
  bestThirds?: number;
  /**
   * Knockout ties already played, used to condition the simulation once the bracket is underway.
   * Keyed on the two teams; a recorded result fixes that tie instead of re-simulating it.
   */
  knockout?: MatchResult[];
}

export interface RunOptions {
  sims: number;
  seed: number;
}

export interface TeamStageProbs {
  team: TeamId;
  group: string;
  winGroup: number;
  runnerUp: number;
  bestThird: number;
  escapeGroup: number;
  /** 95% Monte Carlo margin of error on escapeGroup. */
  escapeMoE: number;
}

export interface RunMetadata {
  sims: number;
  seed: number;
  bestThirds: number;
}

export interface ResultSet {
  teams: TeamStageProbs[];
  metadata: RunMetadata;
}

interface Counts {
  group: string;
  winGroup: number;
  runnerUp: number;
  bestThird: number;
  escapeGroup: number;
}

const Z95 = 1.959964;

export function runGroupStage(input: TournamentInput, model: StrengthModel, opts: RunOptions): ResultSet {
  const bestThirds = input.bestThirds ?? 8;
  const rng = mulberry32(opts.seed);

  const counts = new Map<TeamId, Counts>();
  for (const g of input.groups) {
    for (const t of g.teams) {
      counts.set(t.id, { group: g.group, winGroup: 0, runnerUp: 0, bestThird: 0, escapeGroup: 0 });
    }
  }

  for (let s = 0; s < opts.sims; s++) {
    const results = input.groups.map((g) => completeGroup(g, model, rng));
    const q = selectQualifiers(results, { bestThirds });
    const winners = new Set(q.winners);
    const runners = new Set(q.runnersUp);
    const thirds = new Set(q.bestThirds);

    for (const team of counts.keys()) {
      const c = counts.get(team)!;
      if (winners.has(team)) {
        c.winGroup += 1;
        c.escapeGroup += 1;
      } else if (runners.has(team)) {
        c.runnerUp += 1;
        c.escapeGroup += 1;
      } else if (thirds.has(team)) {
        c.bestThird += 1;
        c.escapeGroup += 1;
      }
    }
  }

  const n = opts.sims;
  const moe = (count: number): number => {
    const p = count / n;
    return Z95 * Math.sqrt((p * (1 - p)) / n);
  };

  const teams: TeamStageProbs[] = [...counts.entries()]
    .map(([team, c]) => ({
      team,
      group: c.group,
      winGroup: c.winGroup / n,
      runnerUp: c.runnerUp / n,
      bestThird: c.bestThird / n,
      escapeGroup: c.escapeGroup / n,
      escapeMoE: moe(c.escapeGroup),
    }))
    .sort((a, b) => b.escapeGroup - a.escapeGroup || a.team.localeCompare(b.team));

  return { teams, metadata: { sims: n, seed: opts.seed, bestThirds } };
}

src/engine/standings.ts.source:
// Group standings + FIFA 2026 Article 13 tiebreakers.
//
// Order after equal points:
//   1. H2H points  2. H2H GD  3. H2H goals   (computed among the tied subset only)
//   4. overall GD  5. overall goals  6. conduct/fair-play  7. FIFA ranking   (8. lots)
//
// Head-to-head precedes overall goal difference (the 2026 reversal of 2022), and a tie that
// only partly resolves is re-evaluated from the top among the still-tied subset — so H2H is
// recomputed against the smaller set. Validated by spike S2; this is the production module.
import type { MatchResult, TableRow, TeamId, TeamMeta } from "../domain/types";

const WIN = 3;
const DRAW = 1;

interface Tally {
  played: number;
  won: number;
  drawn: number;
  lost: number;
  goalsFor: number;
  goalsAgainst: number;
}

function tally(team: TeamId, matches: MatchResult[]): Tally {
  const t: Tally = { played: 0, won: 0, drawn: 0, lost: 0, goalsFor: 0, goalsAgainst: 0 };
  for (const m of matches) {
    let scored: number;
    let conceded: number;
    if (m.home === team) {
      scored = m.homeGoals;
      conceded = m.awayGoals;
    } else if (m.away === team) {
      scored = m.awayGoals;
      conceded = m.homeGoals;
    } else {
      continue;
    }
    t.played += 1;
    t.goalsFor += scored;
    t.goalsAgainst += conceded;
    if (scored > conceded) t.won += 1;
    else if (scored === conceded) t.drawn += 1;
    else t.lost += 1;
  }
  return t;
}

const points = (t: Tally) => t.won * WIN + t.drawn * DRAW;
const goalDiff = (t: Tally) => t.goalsFor - t.goalsAgainst;

interface Ctx {
  all: MatchResult[];
  meta: Map<TeamId, TeamMeta>;
}

type Criterion = (team: TeamId, ctx: Ctx) => number;

/** Head-to-head criteria over `within` (the matches played among the tied subset only). */
function h2hCriteria(within: MatchResult[]): Criterion[] {
  return [
    (team) => points(tally(team, within)),
    (team) => goalDiff(tally(team, within)),
    (team) => tally(team, within).goalsFor,
  ];
}

const overallCriteria: Criterion[] = [
  (team, ctx) => goalDiff(tally(team, ctx.all)),
  (team, ctx) => tally(team, ctx.all).goalsFor,
  (team, ctx) => ctx.meta.get(team)?.conduct ?? 0,
  // Lower FIFA rank is better → negate so "higher score first" holds throughout.
  (team, ctx) => -(ctx.meta.get(team)?.fifaRank ?? Number.POSITIVE_INFINITY),
];

function partition(teams: TeamId[], score: Criterion, ctx: Ctx): TeamId[][] {
  const scored = teams.map((id) => ({ id, s: score(id, ctx) }));
  scored.sort((a, b) => b.s - a.s);
  const buckets: TeamId[][] = [];
  for (const { id, s } of scored) {
    const last = buckets[buckets.length - 1];
    if (last && score(last[0], ctx) === s) last.push(id);
    else buckets.push([id]);
  }
  return buckets;
}

interface Resolved {
  id: TeamId;
  byLots: boolean;
}

/** Resolve a points-tied subset via criteria, re-applying H2H among any shrunken tie. */
function resolve(subset: TeamId[], ctx: Ctx): Resolved[] {
  if (subset.length === 1) return [{ id: subset[0], byLots: false }];

  // Matches among only the tied teams — computed once, so H2H reflects the current subset.
  const inSet = new Set(subset);
  const within = ctx.all.filter((m) => inSet.has(m.home) && inSet.has(m.away));
  const criteria = [...h2hCriteria(within), ...overallCriteria];
  for (const criterion of criteria) {
    const buckets = partition(subset, criterion, ctx);
    if (buckets.length > 1) {
      return buckets.flatMap((b) => (b.length === 1 ? [{ id: b[0], byLots: false }] : resolve(b, ctx)));
    }
  }
  // Nothing separated them → drawing of lots. Deterministic by id for reproducibility.
  return [...subset]
    .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
    .map((id, idx) => ({ id, byLots: idx > 0 }));
}

/** Rank a group: order by overall points, break ties via Article 13, emit full rows. */
export function rankGroup(teams: TeamMeta[], matches: MatchResult[]): TableRow[] {
  const ctx: Ctx = { all: matches, meta: new Map(teams.map((t) => [t.id, t])) };
  const ordered = partition(teams.map((t) => t.id), (team, c) => points(tally(team, c.all)), ctx).flatMap(
    (bucket) => (bucket.length === 1 ? [{ id: bucket[0], byLots: false }] : resolve(bucket, ctx)),
  );

  return ordered.map((r, idx) => {
    const t = tally(r.id, matches);
    return {
      team: r.id,
      position: idx + 1,
      played: t.played,
      won: t.won,
      drawn: t.drawn,
      lost: t.lost,
      goalsFor: t.goalsFor,
      goalsAgainst: t.goalsAgainst,
      goalDifference: goalDiff(t),
      points: points(t),
      ...(r.byLots ? { rankedByLots: true } : {}),
    };
  });
}

